import React, { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { 
  MessageCircle, X, Paperclip, Smile, 
  Send, Clock, Check, CheckCheck,
  User, AlertCircle, Loader2
} from 'lucide-react';
import { io } from 'socket.io-client';

const ChatModal = ({ currentUser, isAuthenticated, onClose }) => {
  const navigate = useNavigate();
  const [messages, setMessages] = useState([]);
  const [inputMessage, setInputMessage] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [conversation, setConversation] = useState(null);
  const [adminInfo, setAdminInfo] = useState(null);
  const [socket, setSocket] = useState(null);
  const [error, setError] = useState(null);
  const [isSending, setIsSending] = useState(false);
  const messagesEndRef = useRef(null);
  const chatInputRef = useRef(null);
  const typingTimeoutRef = useRef(null);

  // URL de base pour les APIs
  const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';
  const SOCKET_URL = process.env.REACT_APP_SOCKET_URL || 'http://localhost:5000';

  // Récupérer le token
  const getAuthToken = () => {
    return localStorage.getItem('authToken');
  };

  // Initialiser Socket.io
  useEffect(() => {
    if (isAuthenticated && currentUser) {
      const token = getAuthToken();
      if (!token) {
        setError('Token d\'authentification manquant');
        return;
      }

      const newSocket = io(SOCKET_URL, {
        auth: { token },
        transports: ['websocket', 'polling'],
        reconnection: true,
        reconnectionAttempts: 5,
        reconnectionDelay: 1000,
      });

      newSocket.on('connect', () => {
        console.log('✅ Connecté au serveur Socket.io');
        setError(null);
      });

      newSocket.on('connect_error', (err) => {
        console.error('❌ Erreur de connexion Socket.io:', err.message);
        setError('Connexion au chat temporairement indisponible');
      });

      newSocket.on('new_message', (message) => {
        console.log('📨 Nouveau message reçu:', message);
        handleNewMessage(message);
      });

      newSocket.on('user_typing', (data) => {
        if (data.conversationId === conversation?.id && data.userId !== currentUser.id) {
          setIsTyping(true);
          setTimeout(() => setIsTyping(false), 2000);
        }
      });

      newSocket.on('message_read', (data) => {
        if (data.conversationId === conversation?.id) {
          updateMessageStatus(data.messageIds, 'read');
        }
      });

      setSocket(newSocket);

      return () => {
        newSocket.disconnect();
      };
    }
  }, [isAuthenticated, currentUser, conversation?.id]);

  // Charger ou créer une conversation
  useEffect(() => {
    if (isAuthenticated && currentUser) {
      loadOrCreateConversation();
    }
  }, [isAuthenticated, currentUser]);

  const loadOrCreateConversation = async () => {
    try {
      setIsLoading(true);
      setError(null);
      const token = getAuthToken();

      if (!token) {
        setError('Session expirée. Veuillez vous reconnecter.');
        navigate('/login');
        return;
      }

      const config = {
        headers: { 
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      };

      // 1. Récupérer les conversations de l'utilisateur
      console.log('📡 Récupération des conversations...');
      const conversationsResponse = await axios.get(
        `${API_URL}/messages/conversations`,
        config
      );

      let conversationData = null;

      if (conversationsResponse.data.success && conversationsResponse.data.conversations) {
        // Chercher une conversation active
        conversationData = conversationsResponse.data.conversations.find(
          conv => conv.status === 'open' || conv.status === 'pending'
        );

        // Sinon, prendre la plus récente
        if (!conversationData && conversationsResponse.data.conversations.length > 0) {
          conversationData = conversationsResponse.data.conversations[0];
        }
      }

      // 2. Si aucune conversation, en créer une nouvelle
      if (!conversationData) {
        console.log('🆕 Création d\'une nouvelle conversation...');

        // Récupérer un admin
        let adminId = null;
        try {
          const adminsResponse = await axios.get(`${API_URL}/users/admins`, config);
          if (adminsResponse.data.success && adminsResponse.data.admins.length > 0) {
            adminId = adminsResponse.data.admins[0].id;
          }
        } catch (adminError) {
          console.warn('Aucun admin trouvé, utilisation de l\'admin par défaut');
          adminId = 1; // ID de l'admin par défaut
        }

        const newConversationData = {
          title: `Support - ${currentUser.first_name}`,
          admin_id: adminId
        };

        const createResponse = await axios.post(
          `${API_URL}/messages/conversations`,
          newConversationData,
          config
        );

        if (createResponse.data.success) {
          conversationData = createResponse.data.conversation;
        } else {
          throw new Error('Échec de la création de la conversation');
        }
      }

      // 3. Charger les messages de la conversation
      if (conversationData) {
        setConversation(conversationData);
        await loadMessages(conversationData.id);

        // 4. Charger les infos de l'admin
        if (conversationData.admin_id) {
          await loadAdminInfo(conversationData.admin_id);
        }
      }

    } catch (error) {
      console.error('❌ Erreur lors du chargement de la conversation:', error);
      setError(error.response?.data?.message || 'Impossible de charger le chat');
      setMessages([]); // Assurez-vous que les messages sont vides en cas d'erreur
    } finally {
      setIsLoading(false);
    }
  };

  const loadAdminInfo = async (adminId) => {
    try {
      const token = getAuthToken();
      const config = {
        headers: { 'Authorization': `Bearer ${token}` }
      };

      const response = await axios.get(`${API_URL}/users/${adminId}`, config);

      if (response.data.success) {
        setAdminInfo(response.data.user);
      } else {
        setAdminInfo({
          id: adminId,
          first_name: 'Conseiller',
          last_name: 'Nexus',
          role: 'admin'
        });
      }
    } catch (error) {
      console.error('Erreur lors du chargement des infos admin:', error);
      setAdminInfo({
        id: adminId,
        first_name: 'Conseiller',
        last_name: 'Nexus',
        role: 'admin'
      });
    }
  };

  const loadMessages = async (conversationId) => {
    try {
      console.log(`📨 Chargement des messages pour la conversation ${conversationId}...`);
      const token = getAuthToken();
      const config = {
        headers: { 'Authorization': `Bearer ${token}` }
      };

      const response = await axios.get(
        `${API_URL}/messages/conversations/${conversationId}/messages`,
        config
      );

      console.log('Réponse messages:', response.data);

      if (response.data.success) {
        const messagesData = response.data.messages || [];
        console.log(`${messagesData.length} messages chargés`);

        // Formater les messages
        const formattedMessages = messagesData.map(msg => ({
          ...msg,
          sender: {
            id: msg.sender_id,
            first_name: msg.sender_id === currentUser.id ? currentUser.first_name : 'Conseiller',
            last_name: msg.sender_id === currentUser.id ? currentUser.last_name : 'Nexus'
          }
        }));

        setMessages(formattedMessages);
        scrollToBottom();
      } else {
        console.warn('Aucun message trouvé');
        setMessages([]);
      }
    } catch (error) {
      console.error('❌ Erreur lors du chargement des messages:', error);
      setMessages([]);
    }
  };

  const handleNewMessage = (message) => {
    // Vérifier si le message appartient à la conversation actuelle
    if (message.conversation_id === conversation?.id) {
      setMessages(prev => [...prev, {
        ...message,
        sender: {
          id: message.sender_id,
          first_name: message.sender_id === currentUser.id ? currentUser.first_name : 'Conseiller',
          last_name: message.sender_id === currentUser.id ? currentUser.last_name : 'Nexus'
        }
      }]);
      scrollToBottom();
    }
  };

  const updateMessageStatus = (messageIds, status) => {
    setMessages(prev => prev.map(msg => 
      messageIds.includes(msg.id) 
        ? { ...msg, status, is_read: status === 'read' }
        : msg
    ));
  };

  const handleSendMessage = async () => {
    const messageContent = inputMessage.trim();
    if (!messageContent || !conversation || isSending) return;

    try {
      setIsSending(true);
      const token = getAuthToken();

      if (!token) {
        setError('Session expirée');
        navigate('/login');
        return;
      }

      const config = {
        headers: { 
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      };

      // Message temporaire
      const tempMessage = {
        id: `temp-${Date.now()}`,
        content: messageContent,
        sender_id: currentUser.id,
        conversation_id: conversation.id,
        created_at: new Date().toISOString(),
        is_read: false,
        is_temp: true,
        sender: {
          id: currentUser.id,
          first_name: currentUser.first_name,
          last_name: currentUser.last_name
        }
      };

      // Ajouter le message temporaire
      setMessages(prev => [...prev, tempMessage]);
      setInputMessage('');
      scrollToBottom();

      // Envoyer via API
      const response = await axios.post(
        `${API_URL}/messages`,
        {
          conversation_id: conversation.id,
          content: messageContent
        },
        config
      );

      if (response.data.success) {
        // Remplacer le message temporaire
        const realMessage = response.data.message;
        setMessages(prev => prev.map(msg => 
          msg.id === tempMessage.id 
            ? {
                ...realMessage,
                sender: {
                  id: currentUser.id,
                  first_name: currentUser.first_name,
                  last_name: currentUser.last_name
                }
              }
            : msg
        ));

        // Émettre via socket
        if (socket && socket.connected) {
          socket.emit('send_message', {
            conversationId: conversation.id,
            message: realMessage
          });
        }

      } else {
        throw new Error('Échec de l\'envoi');
      }

    } catch (error) {
      console.error('❌ Erreur lors de l\'envoi du message:', error);
      setError('Impossible d\'envoyer le message');

      // Marquer le message comme erreur
      setMessages(prev => prev.map(msg => 
        msg.id?.startsWith('temp-') 
          ? { ...msg, error: true, content: `${msg.content} (Échec de l'envoi)` }
          : msg
      ));
    } finally {
      setIsSending(false);
    }
  };

  const handleTyping = () => {
    if (socket && socket.connected && conversation && inputMessage.trim()) {
      socket.emit('typing', {
        conversationId: conversation.id,
        userId: currentUser.id
      });
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const scrollToBottom = () => {
    setTimeout(() => {
      messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, 100);
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const formatTime = (dateString) => {
    try {
      const date = new Date(dateString);
      return date.toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });
    } catch {
      return '--:--';
    }
  };

  const handleRetry = () => {
    setError(null);
    loadOrCreateConversation();
  };

  // Si non authentifié
  if (!isAuthenticated || !currentUser) {
    return (
      <div className="fixed bottom-6 right-6 w-80 sm:w-96 bg-white dark:bg-neutral-900 rounded-2xl shadow-2xl border dark:border-neutral-800 z-50">
        <div className="p-4 bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-t-2xl">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-3">
              <div className="h-10 w-10 rounded-full bg-white/20 flex items-center justify-center">
                <MessageCircle className="h-5 w-5" />
              </div>
              <div>
                <h3 className="font-bold">Support Nexus</h3>
                <p className="text-xs opacity-90">Connectez-vous pour chatter</p>
              </div>
            </div>
            <button onClick={onClose} className="p-2 hover:bg-white/20 rounded-lg">
              <X className="h-5 w-5" />
            </button>
          </div>
        </div>
        <div className="p-6 text-center">
          <MessageCircle className="h-12 w-12 text-gray-400 mx-auto mb-4" />
          <p className="text-gray-600 dark:text-gray-300 mb-4">
            Connectez-vous pour discuter avec notre équipe de support
          </p>
          <button
            onClick={() => navigate('/login')}
            className="w-full py-3 bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-xl font-medium hover:opacity-90 mb-3"
          >
            Se connecter
          </button>
          <button
            onClick={onClose}
            className="w-full py-3 border border-neutral-300 dark:border-neutral-700 rounded-xl font-medium hover:bg-neutral-100 dark:hover:bg-neutral-800"
          >
            Fermer
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="fixed bottom-6 right-6 w-80 sm:w-96 bg-white dark:bg-neutral-900 rounded-2xl shadow-2xl border dark:border-neutral-800 z-50">
      {/* Header */}
      <div className="p-4 bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-t-2xl">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="h-10 w-10 rounded-full bg-white/20 flex items-center justify-center">
              <User className="h-5 w-5" />
            </div>
            <div>
              <h3 className="font-bold">
                {adminInfo ? `${adminInfo.first_name} ${adminInfo.last_name}` : 'Support Nexus'}
              </h3>
              <p className="text-xs opacity-90">
                {adminInfo?.role === 'admin' ? 'Conseiller' : 'Support'} • {isLoading ? 'Connexion...' : 'En ligne'}
              </p>
            </div>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-white/20 rounded-lg">
            <X className="h-5 w-5" />
          </button>
        </div>
      </div>

      {/* Messages */}
      <div className="h-64 sm:h-72 p-4 overflow-y-auto bg-gray-50 dark:bg-neutral-950">
        {error && !isLoading ? (
          <div className="flex flex-col items-center justify-center h-full space-y-3">
            <AlertCircle className="h-12 w-12 text-red-500" />
            <p className="text-center text-red-600 dark:text-red-400">{error}</p>
            <button
              onClick={handleRetry}
              className="px-4 py-2 bg-primary-500 text-white rounded-lg hover:bg-primary-600"
            >
              Réessayer
            </button>
          </div>
        ) : isLoading ? (
          <div className="flex flex-col items-center justify-center h-full space-y-4">
            <Loader2 className="h-8 w-8 animate-spin text-primary-500" />
            <p className="text-gray-600 dark:text-gray-400">Chargement des messages...</p>
          </div>
        ) : messages.length === 0 ? (
          <div className="text-center py-8">
            <MessageCircle className="h-12 w-12 text-gray-400 mx-auto mb-3" />
            <p className="text-gray-600 dark:text-gray-400">
              Aucun message. Commencez la conversation !
            </p>
          </div>
        ) : (
          <div className="space-y-3">
            {messages.map((message) => (
              <div
                key={message.id}
                className={`flex ${message.sender_id === currentUser.id ? 'justify-end' : 'justify-start'}`}
              >
                <div className={`max-w-[85%] rounded-2xl p-3 ${
                  message.sender_id === currentUser.id
                    ? 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-br-none'
                    : 'bg-white dark:bg-neutral-800 text-gray-900 dark:text-white rounded-bl-none border'
                } ${message.error ? 'border-red-300' : ''}`}>
                  <p className="text-sm">{message.content}</p>
                  <div className={`flex items-center justify-between mt-2 text-xs ${
                    message.sender_id === currentUser.id ? 'text-white/80' : 'text-gray-500'
                  }`}>
                    <span>{formatTime(message.created_at)}</span>
                    {message.sender_id === currentUser.id && (
                      <span>
                        {message.is_read ? <CheckCheck className="h-3 w-3 inline ml-1" /> : <Check className="h-3 w-3 inline ml-1" />}
                      </span>
                    )}
                  </div>
                </div>
              </div>
            ))}

            {isTyping && (
              <div className="flex justify-start">
                <div className="bg-white dark:bg-neutral-800 rounded-2xl rounded-bl-none p-3 border">
                  <div className="flex items-center space-x-2">
                    <div className="flex space-x-1">
                      <div className="h-2 w-2 bg-gray-400 rounded-full animate-bounce"></div>
                      <div className="h-2 w-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></div>
                      <div className="h-2 w-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></div>
                    </div>
                    <span className="text-xs text-gray-500">écrit...</span>
                  </div>
                </div>
              </div>
            )}

            <div ref={messagesEndRef} />
          </div>
        )}
      </div>

      {/* Input */}
      <div className="p-3 border-t dark:border-neutral-800 bg-white dark:bg-neutral-900 rounded-b-2xl">
        <div className="flex items-center space-x-2">
          <div className="flex-1 relative">
            <input
              ref={chatInputRef}
              type="text"
              value={inputMessage}
              onChange={(e) => {
                setInputMessage(e.target.value);
                handleTyping();
              }}
              onKeyPress={handleKeyPress}
              placeholder="Écrivez votre message..."
              className="w-full pl-4 pr-12 py-3 rounded-xl border bg-white dark:bg-neutral-800 focus:outline-none focus:ring-2 focus:ring-primary-500"
              disabled={isLoading || isSending}
            />
            <div className="absolute right-3 top-1/2 transform -translate-y-1/2 flex items-center space-x-2">
              <button className="p-1 hover:bg-gray-100 dark:hover:bg-neutral-700 rounded">
                <Smile className="h-4 w-4 text-gray-500" />
              </button>
              <button className="p-1 hover:bg-gray-100 dark:hover:bg-neutral-700 rounded">
                <Paperclip className="h-4 w-4 text-gray-500" />
              </button>
            </div>
          </div>
          <button
            onClick={handleSendMessage}
            disabled={!inputMessage.trim() || isLoading || isSending}
            className="p-3 rounded-xl bg-primary-500 text-white hover:bg-primary-600 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isSending ? <Loader2 className="h-5 w-5 animate-spin" /> : <Send className="h-5 w-5" />}
          </button>
        </div>
      </div>
    </div>
  );
};

export default ChatModal;
